    """Frais par défaut (Wave 1 %, décision du 09/11/2026) et coordonnées déjà saisies avant ce lot reprises comme validées,
    pour ne pas bloquer les prochains versements. La comptable peut les revoir dans « Moyens de paiement »."""
    FraisVersement = apps.get_model('management', 'FraisVersement')
    Vendeur = apps.get_model('management', 'Vendeur')
    for moyen, taux in (('wave', 1), ('orange', 0), ('mtn', 0), ('moov', 0), ('virement', 0)):
        FraisVersement.objects.get_or_create(moyen=moyen, defaults={'taux': taux})
    for v in Vendeur.objects.exclude(compte_versement__isnull=True).exclude(compte_versement='').exclude(moyen_versement__isnull=True):
        v.moyen_valide, v.compte_valide, v.titulaire_valide = v.moyen_versement, v.compte_versement, v.titulaire_versement or ''
        v.versement_valide = True
        v.save(update_fields=['moyen_valide', 'compte_valide', 'titulaire_valide', 'versement_valide'])


